($liveResources['dark_matter'] ?? 0))?></strong></span></div><div class="resource resource-food"><em>F</em><span><small>Food</small><strong><?=number_format((int)($liveResources['food'] ?? 0))?></strong></span></div><div class="resource resource-water"><em>W</em><span><small>Water</small><strong><?=number_format((int)($liveResources['water'] ?? 0))?></strong></span></div><div class="resource resource-population"><em>POP</em><span><small>Population</small><strong><?=number_format((float)($liveResources['population'] ?? 150000), 2)?> / <?=number_format((float)($liveResources['population_capacity'] ?? 200000), 2)?></strong></span></div><span class="badge">TURN 84</span><span class="badge good">SERVER <?=htmlspecialchars($appMeta['server_status'])?></span><div class="account-menu"><button class="account-menu-toggle" type="button" aria-expanded="false" aria-controls="account-panel" onclick="toggleAccountMenu(event)"><span aria-hidden="true">⚙</span><span class="account-label">Account</span><strong>Tanang</strong></button><div id="account-panel" class="account-panel" role="menu" aria-label="Account options"><h3>Commander settings</h3><p>Authenticated account · session protected</p><button class="account-action" type="button" onclick="accountNavigate('account-info')">Account overview <span>→</span></button><button class="account-action" type="button" onclick="accountNavigate('resources')">Resources &amp; vault <span>→</span></button><button class="account-action" type="button" onclick="accountNavigate('race')">Race &amp; government <span>→</span></button><button class="account-action" type="button" onclick="accountRefresh()">Refresh live state <span>↻</span></button><label for="account-density">Display density<select id="account-density" onchange="setAccountDensity(this.value)"><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></label><label for="account-theme">Interface theme<select id="account-theme" onchange="setAccountTheme(this.value)"><option value="default-white">Default White</option><option value="window-blue">Window Blue Sci-Fi</option><option value="deep-space-blue">Deep Space Blue</option></select></label><label for="account-reduced-motion">Reduce motion<input id="account-reduced-motion" type="checkbox" onchange="setAccountMotion(this.checked)"></label><a class="account-action account-danger" role="menuitem" href="actions/logout.php">Sign out <span>↗</span></a><div class="account-meta">CSRF, RBAC, ownership, and transaction checks remain server-authoritative.</div></div></div></div></header><section class="content"><div class="heading"><div><div class="eyebrow" id="section">COMMAND CENTER</div><h1 id="title">Command Center</h1><p id="description">Server-authoritative colony operations, life support, queues, fleet movement, and turn settlement in one game dashboard.</p></div></div><div id="content"></div></section><footer class="footer"><div><strong><?=htmlspecialchars($appMeta['name'])?></strong> <span>v<?=htmlspecialchars($appMeta['version'])?> · build <?=htmlspecialchars($appMeta['build'])?></span><div class="footer-developers">Developed by <?=htmlspecialchars($appMeta['developers']['lead'])?> · <?=htmlspecialchars($appMeta['developers']['team'])?></div></div><div class="footer-links"><a href="<?=htmlspecialchars($appMeta['legal']['rules'])?>">Rules</a><a href="<?=htmlspecialchars($appMeta['legal']['terms'])?>">Terms</a><a href="<?=htmlspecialchars($appMeta['legal']['privacy'])?>">Privacy</a><a href="<?=htmlspecialchars($appMeta['legal']['status'])?>">Status</a><span><?=htmlspecialchars($appMeta['copyright'])?></span></div></footer></main></div><script>
const registry=<?=$registryJson?>,details=<?=$pageDetailsJson?>,routeDetails=<?=$routeDetailsJson?>,detailedSpecs=<?=$detailedPageSpecsJson?>,interactions=<?=$interactionJson?>,pageContracts=<?=$pageContractsJson?>,state=<?=$stateJson?>,permissions=<?=$permissionJson?>;const nav=document.getElementById('nav');const requestedPageRaw=new URLSearchParams(window.location.search).get('page')||'dashboard';const requestedPage=requestedPageRaw==='planets'?'planet-list':requestedPageRaw;const registryHasPage=Object.values(registry).some(group=>group&&group.pages&&Object.prototype.hasOwnProperty.call(group.pages,requestedPage));let selected=Object.prototype.hasOwnProperty.call(routeDetails,requestedPage)||registryHasPage?requestedPage:'dashboard';const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));const fmt=n=>Number(n).toLocaleString();const fmtPopulation=n=>Number(n).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
function toggleAccountMenu(event){if(event)event.stopPropagation();const panel=document.getElementById('account-panel');const toggle=document.querySelector('.account-menu-toggle');if(!panel)return;const open=panel.classList.toggle('open');if(toggle)toggle.setAttribute('aria-expanded',open?'true':'false')}function closeAccountMenu(){const panel=document.getElementById('account-panel');const toggle=document.querySelector('.account-menu-toggle');if(panel)panel.classList.remove('open');if(toggle)toggle.setAttribute('aria-expanded','false')}function accountNavigate(page){closeAccountMenu();selected=page;render();history.replaceState({},'', 'game.php?page='+encodeURIComponent(page))}function accountRefresh(){closeAccountMenu();window.location.reload()}function setAccountDensity(value){document.documentElement.dataset.density=value;localStorage.setItem('sgw_density',value)}function setAccountTheme(value){const theme=['window-blue','deep-space-blue'].includes(value)?value:'default-white';document.documentElement.dataset.theme=theme;localStorage.setItem('sgw_theme',theme)}function setAccountMotion(reduced){document.documentElement.dataset.reducedMotion=reduced?'true':'false';localStorage.setItem('sgw_reduced_motion',reduced?'true':'false')}function loadAccountPreferences(){const density=localStorage.getItem('sgw_density')||'comfortable';const storedTheme=localStorage.getItem('sgw_theme');const theme=['window-blue','deep-space-blue'].includes(storedTheme)?storedTheme:'default-white';const reduced=localStorage.getItem('sgw_reduced_motion')==='true';document.documentElement.dataset.density=density;document.documentElement.dataset.theme=theme;document.documentElement.dataset.reducedMotion=reduced?'true':'false';const densitySelect=document.getElementById('account-density');const themeSelect=document.getElementById('account-theme');const motionToggle=document.getElementById('account-reduced-motion');if(densitySelect)densitySelect.value=density;if(themeSelect)themeSelect.value=theme;if(motionToggle)motionToggle.checked=reduced;document.addEventListener('click',event=>{if(!event.target.closest('.account-menu'))closeAccountMenu()})}function flatten(){const out=[];Object.entries(registry).forEach(([groupKey,g])=>Object.entries(g.pages||{}).forEach(([key,p])=>out.push({groupKey,group:g.label||groupKey,key,...p})));return out}const all=flatten();
function renderNav(filter=''){nav.innerHTML='';Object.entries(registry).forEach(([groupKey,g])=>{const pages=Object.entries(g.pages||{}).filter(([key,p])=>{const hay=(key+' '+(p.title||'')+' '+(p.actions||[]).join(' ')+' '+(p.tables||[]).join(' ')).toLowerCase();return !filter||hay.includes(filter)});if(!pages.length)return;const d=document.createElement('details');d.open=true;const s=document.createElement('summary');s.textContent=(g.icon||'')+' '+(g.label||groupKey);d.appendChild(s);const sub=document.createElement('div');sub.className='sub';pages.forEach(([key,p])=>{const b=document.createElement('button');b.className='link'+(key===selected?' active':'');b.innerHTML='<span>'+esc(p.title)+'</span><small>'+esc(p.layout)+'</small>';b.onclick=()=>{selected=key;render()};sub.appendChild(b)});d.appendChild(sub);nav.appendChild(d)})}
function actionButton(key,label,cls=''){return permissions[key]?'<button class="button '+cls+' server-action" data-action="'+key+'">'+label+'</button>':'<button class="button" disabled>'+label+' (restricted)</button>'}
function commandCenter(){const c=state.colony;const progression=state.progression;const headerResourceOrder=['metal','crystal','deuterium','naquadah','energy','dark_matter','food','water','population'];const resourceTiles=headerResourceOrder.filter(key=>Object.prototype.hasOwnProperty.call(state.resources,key)).map(key=>{const value=state.resources[key];const capacity=key==='deuterium'?Number(state.resources.deuterium_capacity||100000):(key==='population'?Number(state.resources.population_capacity||200000):12400);const ratio=capacity>0?Math.min(100,Math.max(10,Math.round(Number(value)/capacity*100))):10;return '<div class="resource-tile resource-'+key+'"><small>'+esc(key.replace('_',' '))+'</small><strong>'+(key==='population'?fmtPopulation(value):fmt(value))+'</strong><div class="bar"><i style="width:'+ratio+'%"></i></div></div>'}).join('');const queues=state.queues.map(q=>'<div class="row"><div><strong>'+esc(q.name)+'</strong><small>'+esc(q.kind)+' · '+esc(q.level)+' · '+esc(q.status)+'</small></div><span class="badge">'+esc(q.remaining)+'</span></div>').join('');const missions=state.missions.map(m=>'<div class="row"><div><strong>'+esc(m.type)+'</strong><small>'+esc(m.target)+' · '+esc(m.status)+'</small></div><span class="badge">'+esc(m.eta)+'</span></div>').join('');const buildings=state.buildings.map(b=>'<tr><td>'+esc(b.name)+'</td><td>Level '+b.level+'</td><td>'+esc(b.output)+'</td><td><span class="badge good">'+esc(b.state)+'</span></td></tr>').join('');const alerts=state.alerts.map(a=>'<div class="alert"><strong class="'+esc(a.level)+'">'+esc(a.title)+'</strong><span>'+esc(a.detail)+'</span></div>').join('');document.getElementById('section').textContent='COMMAND CENTER';document.getElementById('title').textContent='Command Center';document.getElementById('description').textContent='Server-authoritative colony operations, life support, queues, fleet movement, and turn settlement in one game dashboard.';document.getElementById('content').innerHTML='<div class="resource-strip">'+resourceTiles+'</div><div class="cc-grid"><div class="card wide"><div class="eyebrow">COLONY OVERVIEW</div><h2>'+esc(c.name)+' <span class="badge">'+esc(c.coordinate)+'</span></h2><div class="metric-grid"><div class="metric"><span>Population</span><strong>'+fmtPopulation(c.population)+' / '+fmtPopulation(c.capacity)+'</strong><small>Capacity utilization '+Math.round(c.population/c.capacity*100)+'%</small></div><div class="metric"><span>Morale</span><strong>'+c.morale+'%</strong><small>Stable colony confidence</small></div><div class="metric"><span>Life support</span><strong>'+fmt(c.food)+' / '+fmt(c.water)+'</strong><small>Food / Water reserves</small></div></div><div class="feedback" style="display:block">Live colony data synchronized successfully.</div></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS</div><h2>Command controls</h2><div class="actions"><div class="action"><span>Process next turn</span>'+actionButton('process_turns','Process turns','dark')+'</div><div class="action"><span>Open target board</span>'+actionButton('choose_target','Choose target')+'</div><div class="action"><span>Read command reports</span>'+actionButton('review_reports','Review reports')+'</div></div><div class="permission">Authenticated commander · CSRF required · RBAC checked · ownership validated · transaction committed server-side.</div><div id="feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">CONSTRUCTION / RESEARCH / SHIPYARD</div><h2>Active queues</h2>'+queues+'</div><div class="card side-card"><div class="eyebrow">LIFE SUPPORT</div><h2>Colony systems</h2><div class="row"><div><strong>Food</strong><small>'+c.food_rate+' / hour consumption</small></div><span class="badge good">NOMINAL</span></div><div class="row"><div><strong>Water</strong><small>'+c.water_rate+' / hour consumption</small></div><span class="badge good">NOMINAL</span></div><div class="row"><div><strong>Morale</strong><small>Population stability</small></div><span class="badge good">'+c.morale+'%</span></div>'+actionButton('open_colony','Open colony')+'</div><div class="card wide"><div class="eyebrow">BUILDING STATUS</div><h2>Colony infrastructure</h2><table class="table"><thead><tr><th>Building</th><th>Level</th><th>Output</th><th>State</th></tr></thead><tbody>'+buildings+'</tbody></table></div><div class="card side-card"><div class="eyebrow">FLEET CONTROL</div><h2>Mission board</h2>'+missions+actionButton('dispatch_fleet','Dispatch fleet')+'</div><div class="card wide"><div class="eyebrow">UNIVERSAL PROGRESSION</div><h2>Tier '+progression.tier+' / Level '+progression.level+' <span class="badge">'+esc(progression.tier_name)+'</span></h2><div class="metric-grid"><div class="metric"><span>Global level</span><strong>'+progression.global_level+' / 483</strong><small>21 tiers × 23 levels</small></div><div class="metric"><span>Next level</span><strong>'+progression.next_level+'</strong><small>'+progression.progress_percent+'% progress</small></div><div class="metric"><span>Current effect</span><strong>+'+progression.effect_percent.toFixed(1)+'%</strong><small>Player progression modifier</small></div></div><div class="bar"><i style="width:'+progression.progress_percent+'%"></i></div><div class="actions" style="margin-top:12px">'+actionButton('progression_advance','Advance player level','dark')+' <span class="badge">Server validates cost, prerequisites, and tier cap</span></div></div><div class="card wide"><div class="eyebrow">COMMAND ALERTS</div><h2>Events and warnings</h2>'+alerts+'</div><div class="card side-card"><div class="eyebrow">COMMAND STATUS</div><h2>Colony systems synchronized</h2><p class="permission">Your colony commands are validated securely and your latest resources, queues, fleets, and progression are synchronized with the game server.</p><span class="badge good">LIVE STATE</span> <span class="badge">SERVER VERIFIED</span><details style="margin-top:14px"><summary>Technical details</summary><p class="permission">The browser submits player intent only. <code>process_turns</code> calls the PHP service layer, settles resources and queues in a transaction, writes an event, and returns refreshed state.</p><span class="badge">process_turns</span> <span class="badge">players</span> <span class="badge">player_resources</span> <span class="badge">rankings</span> <span class="badge">game_events</span></details></div></div>';bindIntentButtons('.server-action','dashboard')}
function accountInfo(){const a=state.account||{commander:'Tanang',username:'tanang',race:"Tau'ri",government:'Stellar Republic',rank:'Commander',level:12,glory:1840,reputation:920,experience:72800,victories:38,defeats:7,protection:'Active',vacation:'Off',registration:'Complete',created:'2026-01-14',lastLogin:'Current session'};document.getElementById('section').textContent='COMMAND CENTER';document.getElementById('title').textContent='Account Information';document.getElementById('description').textContent='Commander identity, faction bonuses, progression, protection, and account security are read from authenticated server state.';document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">COMMANDER PROFILE</div><h2>'+esc(a.commander)+' <span class="badge good">AUTHENTICATED</span></h2><div class="metric-grid"><div class="metric"><span>Username</span><strong>'+esc(a.username)+'</strong><small>Account handle</small></div><div class="metric"><span>Rank</span><strong>'+esc(a.rank)+'</strong><small>Level '+fmt(a.level)+'</small></div><div class="metric"><span>Registration</span><strong>'+esc(a.registration)+'</strong><small>Created '+esc(a.created)+'</small></div></div></div><div class="card side-card"><div class="eyebrow">FACTION IDENTITY</div><h2>'+esc(a.race)+'</h2><div class="row"><div><strong>Government</strong><small>Current political system</small></div><span class="badge">'+esc(a.government)+'</span></div><div class="row"><div><strong>Combined modifiers</strong><small>Race × government</small></div><span class="badge good">APPLIED</span></div><button class="button dark" onclick="openPage(\'race\')">Review faction bonuses</button></div><div class="card wide"><div class="eyebrow">PROGRESSION</div><h2>Glory, Reputation, and experience</h2><div class="metric-grid"><div class="metric"><span>Experience</span><strong>'+fmt(a.experience)+'</strong><small>Level '+fmt(a.level)+' progression</small><div class="bar"><i style="width:72%"></i></div></div><div class="metric"><span>Glory</span><strong>'+fmt(a.glory)+'</strong><small>Ascension resource</small></div><div class="metric"><span>Reputation</span><strong>'+fmt(a.reputation)+'</strong><small>Diplomacy and rank</small></div></div><div class="row"><span>Victories / defeats</span><strong>'+fmt(a.victories)+' / '+fmt(a.defeats)+'</strong></div></div><div class="card side-card"><div class="eyebrow">PROTECTION</div><h2>Account safeguards</h2><div class="row"><div><strong>Protection status</strong><small>Combat eligibility</small></div><span class="badge good">'+esc(a.protection)+'</span></div><div class="row"><div><strong>Vacation mode</strong><small>Long-term protection</small></div><span class="badge">'+esc(a.vacation)+'</span></div><button class="button" onclick="openPage(\'vacation\')">Manage vacation mode</button></div><div class="card wide"><div class="eyebrow">SECURITY AND SESSION</div><h2>Authenticated account state</h2><div class="row"><span>Last login</span><strong>'+esc(a.lastLogin)+'</strong></div><div class="row"><span>Session protection</span><span class="badge good">CSRF + RBAC ENABLED</span></div><div class="row"><span>Data authority</span><span class="badge good">SERVER-SIDE PDO</span></div><p class="permission">Read-only account data is scoped to the authenticated commander. Race changes, government reform, vacation, and ascension use separate CSRF-protected PHP actions.</p></div><div class="card side-card"><div class="eyebrow">ACCOUNT CONTROLS</div><h2>Sub-pages</h2><div class="actions"><button class="button" onclick="openPage(\'race\')">Race and government</button><button class="button" onclick="openPage(\'ascension\')">Progression and ascension</button><button class="button" onclick="openPage(\'messages\')">Account messages</button></div><div class="feedback" style="display:block">State loaded from players, races, governments, rankings, progression, glory, protection, and audit records.</div></div></div>'}function openPage(page){selected=page;render()}function economyPage(){const b=interactions.economy.buttons||{};const r=state.resources;const banked=Number(r.banked_naquadah||0);const controlRows=Object.entries(b).map(([label,x])=>'<div class="action"><div><strong>'+esc(label)+'</strong><small>'+esc(x.logic)+'</small></div>'+actionButton(x.action,label,'dark')+'</div>').join('');document.getElementById('section').textContent='COMMAND CENTER';document.getElementById('title').textContent='Resources & Vault';document.getElementById('description').textContent='Resources & Vault — Validated server-side state transition';document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">PAGE DETAILS</div><h2>Resources & Vault</h2><div class="metric-grid"><div class="metric"><span>Available Naquadah</span><strong>'+fmt(r.naquadah)+'</strong><small>Spendable balance</small></div><div class="metric"><span>Protected vault</span><strong>'+fmt(banked)+'</strong><small>Banked Naquadah</small></div><div class="metric"><span>Dark Matter</span><strong>'+fmt(r.dark_matter)+'</strong><small>Special resource</small></div></div><div class="row"><span>Resource authority</span><span class="badge good">SERVER-VALIDATED</span></div><div class="row"><span>State transition</span><span class="badge">TRANSACTIONAL</span></div></div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Buttons and forms</h2><div class="actions">'+controlRows+'</div><p class="permission">authenticated commander</p></div><div class="card wide"><div class="eyebrow">RESOURCE RESERVES</div><h2>Eight-resource ledger</h2>'+Object.entries(r).map(([key,value])=>'<div class="row"><span>'+esc(key.replace('_',' '))+'</span><strong>'+fmt(value)+'</strong></div>').join('')+'</div><div class="card side-card"><div class="eyebrow">VAULT STATUS</div><h2>Resource transfers ready</h2><p class="permission">Deposit and withdraw Naquadah securely between your available balance and protected vault. The server checks every amount before committing the transfer.</p><span class="badge good">SERVER VERIFIED</span> <span class="badge">VAULT CONTROL ACTIVE</span><details style="margin-top:14px"><summary>Technical details</summary><p class="permission">Actions: <code>deposit</code> / <code>withdraw</code>.</p><span class="badge">player_resources</span> <span class="badge">game_settings</span><p class="permission">Writes are transactional and guarded by authentication, CSRF, RBAC, ownership, cooldown, and resource validation.</p><div style="margin-top:12px">'+['ready','empty','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></details></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','empty','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>'}function breakdownPage(){const b=interactions.breakdown.buttons||{};const inc=state.income||{};const formula=inc.formula||'settlement = (base production × race modifier × government modifier × technology) − upkeep';const base=Number(inc.base_production||0),raceModifier=Number(inc.race_modifier||1),governmentModifier=Number(inc.government_modifier||1),technologyModifier=Number(inc.technology_modifier||1),foodUpkeep=Number((inc.upkeep||{}).food||0),waterUpkeep=Number((inc.upkeep||{}).water||0),energyUpkeep=Number((inc.upkeep||{}).energy||0),gross=Number(inc.gross_output||0),net=Number(inc.net_settlement||0),colonies=inc.colonies||[],primary=colonies[0]||null,stateLabel=inc.state||'empty';const actionRows=Object.entries(b).map(([label,x])=>'<div class="action"><div><strong>'+esc(label)+'</strong><small>'+esc(x.logic)+'</small></div><button class="button income-intent" data-action="'+esc(x.action)+'">'+esc(label)+'</button></div>').join('');const states=['ready','empty','protected','error'];document.getElementById('section').textContent='COMMAND CENTER';document.getElementById('title').textContent='Income Breakdown';document.getElementById('description').textContent='Income Breakdown — '+formula;document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">PAGE DETAILS</div><h2>Income Breakdown</h2><div class="metric-grid"><div class="metric"><span>Base income</span><strong>'+fmt(base)+'</strong><small>Per settlement cycle</small></div><div class="metric"><span>Gross settlement</span><strong>'+fmt(gross)+'</strong><small>Before life-support upkeep</small></div><div class="metric"><span>Net settlement</span><strong>'+fmt(net)+'</strong><small>After food, water, and energy</small></div></div><div class="row"><div><strong>Settlement formula</strong><small>'+formula+'</small></div><span class="badge good">SERVER MODEL</span></div></div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Buttons and forms</h2><div class="actions">'+actionRows+'</div><p class="permission">Authenticated commander · read-only scope · owned colonies only</p><div id="income-feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">MODIFIER BREAKDOWN</div><h2>Race, government, and technology</h2><div class="row"><span>Tau’ri race modifier</span><strong>+'+Math.round((raceModifier-1)*100)+'%</strong></div><div class="row"><span>Stellar Republic economy modifier</span><strong>+'+Math.round((governmentModifier-1)*100)+'%</strong></div><div class="row"><span>Technology multiplier</span><strong>'+technologyModifier.toFixed(2)+'×</strong></div><div class="row"><span>Combined production multiplier</span><strong>'+((raceModifier*governmentModifier*technologyModifier).toFixed(3))+'×</strong></div></div><div class="card side-card"><div class="eyebrow">COLONY PRODUCTION</div><h2>Owned colony comparison</h2><div class="row"><div><strong>'+esc(primary?primary.name:'No owned colonies')+'</strong><small>'+esc(primary?((primary.coordinate||'No coordinate')+' · '+(primary.biome||'Unknown biome')):'Commander-owned colony scope is empty')+'</small></div><span class="badge '+(primary?'good':'')+'">'+(primary?'PRIMARY':'EMPTY')+'</span></div><div class="row"><span>Population workforce</span><strong>'+fmt(primary?primary.population:0)+'</strong></div><div class="row"><span>Colony portfolio</span><strong>'+fmt(inc.colony_count||colonies.length)+'</strong></div><button class="button income-intent" data-action="read_colony_comparison">Compare colonies</button></div><div class="card wide"><div class="eyebrow">FOOD, WATER, AND ENERGY UPKEEP</div><h2>Life-support costs per settlement</h2><div class="metric-grid"><div class="metric"><span>Food upkeep</span><strong>'+fmt(foodUpkeep)+'</strong><small>Population consumption</small></div><div class="metric"><span>Water upkeep</span><strong>'+fmt(waterUpkeep)+'</strong><small>Population consumption</small></div><div class="metric"><span>Energy upkeep</span><strong>'+fmt(energyUpkeep)+'</strong><small>Infrastructure reserve</small></div></div><div class="row"><span>Total upkeep</span><strong>'+fmt(foodUpkeep+waterUpkeep+energyUpkeep)+'</strong></div></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: read-only</p>'+['player_resources','player_colonies','races','government_types','technologies','universe_planets'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">Read actions are authenticated, CSRF-protected, RBAC-checked, and scoped to commander-owned colonies.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+states.map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>';bindIntentButtons('.income-intent','income')}function sabotagePage(){const c=state.covert||{};const targets=state.target_board||[];const formula='damage = bounded system disruption × success probability × covert technology';const rows=targets.map(t=>'<tr><td><strong>'+esc(t.name)+'</strong></td><td>'+esc(t.race)+'</td><td>#'+esc(t.rank)+'</td><td>'+fmt(t.defense)+'</td><td>'+fmt(t.covert)+'</td><td><span class="badge '+(t.status==='PROTECTED'?'':'good')+'">'+esc(t.status)+'</span></td><td><button class="button sabotage-intent" data-target="'+t.id+'" data-action="covert:sabotage" '+(t.status==='PROTECTED'?'disabled':'')+'>Sabotage</button></td></tr>').join('');const selected=targets.find(t=>t.status==='OPEN')||targets[0]||{id:0,name:'No target',covert:0,status:'PROTECTED'};const detection=Math.max(0,(Number(selected.covert)||0)-20-(Number(c.covert_level)||1));const success=Math.max(5,Math.min(95,100-detection));const damage=Math.max(1,Math.min(25,Math.round((Number(c.available_agents)||0)*0.10*(success/100)*(Number(c.covert_level)||1))));document.getElementById('section').textContent='ATTACK';document.getElementById('title').textContent='Sabotage Operations';document.getElementById('description').textContent='Target enemy systems with bounded sabotage damage and detection handling. '+formula;document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">COVERT OPERATIONS</div><h2>Sabotage mission</h2><div class="metric-grid"><div class="metric"><span>Available agents</span><strong>'+fmt(c.available_agents||0)+'</strong><small>Commander covert pool</small></div><div class="metric"><span>Detection formula</span><strong>− agents</strong><small>'+esc(formula.replace('damage = ','detection = defender counter-intelligence − attacker agents − covert technology; damage = '))+'</small></div><div class="metric"><span>Mission state</span><strong>'+esc(c.mission_state||'READY')+'</strong><small>Target and ownership validation required</small></div></div><div class="row"><span>Target intelligence</span><strong>Defense, resources, technology</strong></div><div class="row"><span>Detection handling</span><span class="badge">CLASSIFIED REPORT</span></div></div><div class="card side-card"><div class="eyebrow">MISSION CONTROLS</div><h2>Buttons and forms</h2><div class="actions"><div class="action"><div><strong>Run reconnaissance</strong><small>Generate low-risk target intelligence with detection calculation.</small></div><button class="button sabotage-intent" data-action="covert:recon" data-target="'+selected.id+'">Run reconnaissance</button></div><div class="action"><div><strong>Run spy mission</strong><small>Resolve spy mission and store report.</small></div><button class="button sabotage-intent" data-action="covert:spy" data-target="'+selected.id+'">Run spy mission</button></div><div class="action"><div><strong>Run sabotage</strong><small>Resolve sabotage with detection and damage caps.</small></div><button class="button dark sabotage-intent" data-action="covert:sabotage" data-target="'+selected.id+'" '+(selected.status==='PROTECTED'?'disabled':'')+'>Run sabotage</button></div></div><p class="permission">Authenticated commander · agents required · target ownership validated</p><div id="sabotage-feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">TARGET SYSTEMS</div><h2>Known enemy systems</h2><table class="table"><thead><tr><th>Realm</th><th>Race</th><th>Rank</th><th>Defense</th><th>Counter-intelligence</th><th>Status</th><th>Operation</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="card side-card"><div class="eyebrow">SABOTAGE PREVIEW</div><h2>Bounded damage model</h2><div class="metric-grid"><div class="metric"><span>Selected target</span><strong>'+esc(selected.name)+'</strong><small>'+esc(selected.status)+'</small></div><div class="metric"><span>Detection score</span><strong>'+fmt(detection)+'</strong><small>Defender covert − agents − technology</small></div><div class="metric"><span>Success probability</span><strong>'+fmt(success)+'%</strong><small>Clamped server-side</small></div><div class="metric"><span>Damage cap</span><strong>'+fmt(damage)+'</strong><small>Bounded system disruption</small></div></div><div class="row"><span>Formula</span><span class="badge good">'+esc(formula)+'</span></div></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Attack contract</h2><p class="permission">'+esc(formula)+'</p>'+['target_realms','players','player_resources','protection_states','covert_missions','intelligence_reports','game_events'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">All mutations require authentication, CSRF, RBAC, ownership, protection, resource, cooldown, and transaction checks.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','protected','insufficient-resource','cooldown','success','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>';bindIntentButtons('.sabotage-intent','sabotage')}function reportsPage(){const csrf=state.csrf||'';const reports=state.reports||[];const reportForm=(kind,id,action,label)=>'<form method="post" action="actions/game.php" class="inline-form">'+csrf+'<input type="hidden" name="action" value="'+action+'"><input type="hidden" name="redirect" value="attack-log"><input type="hidden" name="report_kind" value="'+esc(kind||'battle')+'"><input type="hidden" name="report_id" value="'+fmt(id||0)+'"><button class="button" type="submit">'+label+'</button></form>';const fallback=[{report_id:0,report_kind:'battle',title:'No battle reports yet',target_name:'Awaiting combat',action_type:'attack',turns_spent:0,loot:0,attacker_casualties:0,defender_casualties:0,report_text:'No battle report is available.',read_state:'READ',classification:'STANDARD'}];const rows=(reports.length?reports:fallback).map(r=>'<tr><td><strong>'+esc(r.title||r.target_name||'Report')+'</strong></td><td>'+esc(r.action_type||r.report_type||r.report_kind)+'</td><td>'+fmt(r.turns_spent||0)+' turn'+((r.turns_spent||0)===1?'':'s')+'</td><td>'+fmt(r.loot||0)+' Naquadah'+((r.attacker_casualties||r.defender_casualties)?' · '+fmt(r.attacker_casualties||r.defender_casualties)+' casualties':'')+'</td><td><span class="badge '+(r.classification==='CLASSIFIED'?'':'good')+'">'+esc(r.read_state||r.classification||'READ')+'</span></td><td>'+reportForm(r.report_kind,r.report_id,'read_report','Open report')+reportForm(r.report_kind,r.report_id,'message_read','Mark read')+'</td></tr>').join('');document.getElementById('section').textContent='ATTACK';document.getElementById('title').textContent='Attack Log & Reports';document.getElementById('description').textContent='Review battle outcomes, covert reports, casualties, loot, and audit state. report visibility = recipient ownership + classification + read status';document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">BATTLE OUTCOMES</div><h2>Recent reports</h2><table class="table"><thead><tr><th>Report</th><th>Operation</th><th>Turns</th><th>Outcome</th><th>Audit</th><th>Controls</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="card side-card"><div class="eyebrow">REPORT CONTROLS</div><h2>Audit state</h2><div class="action"><div><strong>Open report</strong><small>Verify recipient ownership and classification.</small></div>'+reportForm((reports[0]||{}).report_kind,(reports[0]||{}).report_id,'read_report','Open report')+'</div><div class="action"><div><strong>Mark read</strong><small>Update the recipient read state transactionally.</small></div>'+reportForm((reports[0]||{}).report_kind,(reports[0]||{}).report_id,'message_read','Mark read')+'</div><p class="permission">Recipient ownership and classification are checked server-side.</p><div id="reports-feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Attack contract</h2><p class="permission">report visibility = recipient ownership + classification + read status</p>'+['target_realms','players','player_resources','protection_states','battles','battle_reports','covert_missions','intelligence_reports','game_events'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">Report reads and read-state changes require authentication, CSRF, RBAC, recipient ownership, classification checks, and transactions.</p></div><div class="card side-card"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','protected','insufficient-resource','cooldown','success','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>';bindIntentButtons('.report-intent','attack-log')}function weaponsPage(){const w=state.weapons||{};const owned=w.owned||[];const catalogue=w.catalogue||[];const formula='effective weapon power = base power × condition × technology modifier';const ownedRows=(owned.length?owned:[{name:'No weapons owned',category:'—',quantity:0,power:0,durability:0,max_durability:100,condition_percent:0,technology_modifier:1,effective_power:0,readiness:'UNAVAILABLE'}]).map(x=>'<tr><td><strong>'+esc(x.name)+'</strong></td><td>'+esc(x.category)+'</td><td>'+fmt(x.quantity)+'</td><td>'+fmt(x.durability)+' / '+fmt(x.max_durability)+'</td><td>'+fmt(x.condition_percent)+'%</td><td>'+fmt(x.effective_power)+'</td><td><span class="badge '+(x.readiness==='READY'?'good':'')+'">'+esc(x.readiness)+'</span></td></tr>').join('');const catRows=catalogue.map(x=>'<tr><td><strong>'+esc(x.name)+'</strong></td><td>'+esc(x.category)+'</td><td>'+fmt(x.power)+'</td><td>'+fmt(x.price)+' Naquadah</td><td>'+x.technology_modifier.toFixed(2)+'×</td><td><button class="button weapon-intent" data-action="weapon_buy" data-weapon="'+x.id+'">Buy weapon</button></td></tr>').join('');document.getElementById('section').textContent='ARMORY';document.getElementById('title').textContent='Weapon Inventory';document.getElementById('description').textContent='Weapon Inventory — '+formula;document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">PAGE DETAILS</div><h2>Weapon Inventory</h2><p class="permission">'+esc(formula)+'</p><div class="metric-grid"><div class="metric"><span>Owned weapons</span><strong>'+fmt(owned.length)+'</strong><small>Weapon types in inventory</small></div><div class="metric"><span>Loadout readiness</span><strong>'+fmt(w.loadout_readiness||0)+'</strong><small>Ready weapon systems</small></div><div class="metric"><span>Technology modifier</span><strong>'+((Object.values(w.technology_modifier||{})[0]||1).toFixed(2))+'×</strong><small>Applied to effective power</small></div></div></div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Buttons and forms</h2><div class="action"><div><strong>Buy weapon</strong><small>Validate catalogue item, quantity, balance, and inventory upsert.</small></div><button class="button weapon-intent" data-action="weapon_buy">Buy weapon</button></div><div class="action"><div><strong>Inspect durability</strong><small>Read quantity, durability, power, and assignment state.</small></div><button class="button weapon-intent" data-action="inspect_durability">Inspect durability</button></div><p class="permission">authenticated commander · weapon ownership · resource validation</p><div id="weapon-feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">OWNED WEAPONS</div><h2>Power profile and loadout readiness</h2><table class="table"><thead><tr><th>Weapon</th><th>Category</th><th>Quantity</th><th>Durability</th><th>Condition</th><th>Effective power</th><th>Readiness</th></tr></thead><tbody>'+ownedRows+'</tbody></table></div><div class="card wide"><div class="eyebrow">WEAPON CATALOGUE</div><h2>Available systems</h2><table class="table"><thead><tr><th>Weapon</th><th>Category</th><th>Base power</th><th>Price</th><th>Technology</th><th>Control</th></tr></thead><tbody>'+catRows+'</tbody></table></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: weapon_buy / inspect_durability</p>'+['weapon_types','player_weapons','player_resources'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">Writes are transactional and guarded by authentication, CSRF, RBAC, ownership, cooldown, and resource validation.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','empty','insufficient-resource','success','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>';bindIntentButtons('.weapon-intent','weapons')}
function weaponMarketPage(){const m=state.market||{};const orders=m.orders||[];const own=m.own_orders||[];const history=m.history||[];const fee=Number(m.fee_percent||5);const csrf=state.csrf||'';const escAttr=x=>esc(String(x??'')).replace(/"/g,'&quot;');const weaponOptions=(state.weapons&&state.weapons.catalogue||[]).map(x=>'<option value="'+x.id+'">'+esc(x.name)+' · '+fmt(x.power)+' power</option>').join('');const orderRows=(orders.length?orders:[{id:0,name:'No open weapon listings',seller_name:'—',quantity:0,unit_price:0,power:0,expires_at:null}]).map(o=>'<tr><td><strong>'+esc(o.name)+'</strong><small>'+esc(o.category||'weapon')+'</small></td><td>'+esc(o.seller_name||'Unknown')+'</td><td>'+fmt(o.quantity)+'</td><td>'+fmt(o.unit_price)+' N</td><td>'+fmt((Number(o.quantity||0)*Number(o.unit_price||0)))+' N</td><td>'+esc(o.expires_at||'—')+'</td><td>'+(o.id?'<form method="post" action="actions/game.php" class="inline-form">'+csrf+'<input type="hidden" name="action" value="market_buy"><input type="hidden" name="redirect" value="weapon-market"><input type="hidden" name="order_id" value="'+escAttr(o.id)+'"><input name="quantity" type="number" min="1" max="'+escAttr(o.quantity)+'" value="1" required><button class="button" type="submit">Buy order</button></form>':'<span class="badge">EMPTY</span>')+'</td></tr>').join('');const ownRows=(own.length?own:[{name:'No active orders',quantity:0,unit_price:0,expires_at:'—'}]).map(o=>'<tr><td>'+esc(o.name)+'</td><td>'+fmt(o.quantity)+'</td><td>'+fmt(o.unit_price)+' N</td><td>'+esc(o.expires_at||'—')+'</td></tr>').join('');const histRows=(history.length?history:[{name:'No completed trades',quantity:0,unit_price:0,gross_amount:0,fee_amount:0,seller_net:0,created_at:'—'}]).map(t=>'<tr><td>'+esc(t.name)+'</td><td>'+fmt(t.quantity)+'</td><td>'+fmt(t.unit_price)+' N</td><td>'+fmt(t.gross_amount)+' N</td><td>'+fmt(t.fee_amount)+' N</td><td>'+fmt(t.seller_net)+' N</td><td>'+esc(t.created_at||'—')+'</td></tr>').join('');document.getElementById('section').textContent='ARMORY';document.getElementById('title').textContent='Weapon Market';document.getElementById('description').textContent='Weapon Market — '+(m.formula||'trade settlement = validated order × market price − transaction fee');document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">PAGE DETAILS</div><h2>Weapon Market</h2><p class="permission">'+esc(m.formula||'trade settlement = validated order × market price − transaction fee')+'</p><div class="metric-grid"><div class="metric"><span>Open listings</span><strong>'+fmt(orders.length)+'</strong><small>Live weapon order book</small></div><div class="metric"><span>Transaction fee</span><strong>'+fee.toFixed(2)+'%</strong><small>Deducted from seller settlement</small></div><div class="metric"><span>Price limits</span><strong>'+fmt(m.min_unit_price||100)+'–'+fmt(m.max_unit_price||10000000)+'</strong><small>Naquadah per weapon</small></div></div></div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>List order</h2><form method="post" action="actions/game.php" class="action-form">'+csrf+'<input type="hidden" name="action" value="market_list"><input type="hidden" name="redirect" value="weapon-market"><label>Weapon<select name="weapon_type_id" required>'+weaponOptions+'</select></label><label>Quantity<input name="quantity" type="number" min="1" max="'+fmt(m.max_quantity||100000)+'" value="1" required></label><label>Unit price<input name="unit_price" type="number" min="'+fmt(m.min_unit_price||100)+'" max="'+fmt(m.max_unit_price||10000000)+'" value="1000" required></label><label>Expiry hours<input name="expiry_hours" type="number" min="1" max="168" value="72" required></label><button class="button dark" type="submit">List order →</button></form><p class="permission">authenticated commander · seller ownership · balance validation</p></div><div class="card wide"><div class="eyebrow">ORDER BOOK</div><h2>Open weapon listings</h2><table class="table"><thead><tr><th>Weapon</th><th>Seller</th><th>Quantity</th><th>Unit price</th><th>Gross value</th><th>Expiry</th><th>Control</th></tr></thead><tbody>'+orderRows+'</tbody></table></div><div class="card side-card"><div class="eyebrow">PRICE LIMITS</div><h2>Market rules</h2><div class="row"><span>Minimum unit price</span><strong>'+fmt(m.min_unit_price||100)+' Naquadah</strong></div><div class="row"><span>Maximum unit price</span><strong>'+fmt(m.max_unit_price||10000000)+' Naquadah</strong></div><div class="row"><span>Maximum order quantity</span><strong>'+fmt(m.max_quantity||100000)+'</strong></div><div class="row"><span>Fee settlement</span><strong>Gross − '+fee.toFixed(2)+'%</strong></div></div><div class="card wide"><div class="eyebrow">MY ACTIVE ORDERS</div><h2>Escrowed listings</h2><table class="table"><thead><tr><th>Weapon</th><th>Quantity</th><th>Unit price</th><th>Expiry</th></tr></thead><tbody>'+ownRows+'</tbody></table></div><div class="card wide"><div class="eyebrow">TRADE HISTORY</div><h2>Completed settlements</h2><table class="table"><thead><tr><th>Weapon</th><th>Quantity</th><th>Unit price</th><th>Gross</th><th>Fee</th><th>Seller net</th><th>Time</th></tr></thead><tbody>'+histRows+'</tbody></table></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: market_list / market_buy</p>'+['market_orders','weapon_types','market_transactions','player_weapons','player_resources'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">Writes are transactional and guarded by authentication, CSRF, RBAC, ownership, cooldown, expiry, price limits, and balance validation.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','empty','insufficient-resource','success','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>'}
function technologyRows(techs,csrf,redirect){return (techs.length?techs:[{technology_key:'-',name:'No technologies available',category:'-',level:0,next_level:1,next_cost:0,current_effect:0,next_effect:0,description:'The technology catalogue is empty or has not been seeded yet.',prerequisites:[],ready:false,lock_reason:'No catalogue entry'}]).map(t=>{const prereqs=(t.prerequisites||[]).map(p=>'<div class="row"><span>'+esc(p.key)+' · required '+fmt(p.required||p.required_level||0)+'</span><span class="badge '+(p.met?'good':'')+'">'+(p.met?'MET':'LOCKED')+'</span></div>').join('');const locked=!t.ready||t.technology_key==='-';const control=locked?'<span class="badge">'+esc(t.lock_reason||'LOCKED')+'</span>':'<form method="post" action="actions/game.php" class="inline-form">'+csrf+'<input type="hidden" name="action" value="technology"><input type="hidden" name="redirect" value="'+esc(redirect)+'"><input type="hidden" name="technology_key" value="'+esc(t.technology_key)+'"><button class="button" type="submit">Upgrade</button></form>';return '<tr><td><strong>'+esc(t.name)+'</strong><small>'+esc(t.description||'')+'</small><span class="badge">'+esc(t.category||'')+'</span></td><td>'+fmt(t.level)+'</td><td>'+fmt(t.next_level)+'</td><td>'+fmt(t.next_cost)+' Naquadah</td><td>'+fmt(t.current_effect)+' → '+fmt(t.next_effect)+'</td><td>'+control+'</td></tr><tr><td colspan="6"><div class="prereq-list">'+(prereqs||'<span class="muted">No prerequisite</span>')+'</div></td></tr>'}).join('')}
function renderTechnologyPanel(stateKey,title,branch,formula,description){const d=state[stateKey]||{};const techs=d.technologies||[];const csrf=state.csrf||'';const queue=(d.queue||[]).map(q=>'<div class="row"><div><strong>'+esc(q.technology_key||q.item_key||'Research')+'</strong><small>Level '+fmt(q.level_before||0)+' → '+esc(q.completes_at||'pending')+'</small></div><span class="badge">'+esc(q.status||'queued')+'</span></div>').join('')||'<div class="empty">Research queue available.</div>';const systems=(d.branch_systems||d.weapon_systems||d.agent_systems||d.counter_systems||[]).map(x=>'<div class="row"><span>'+esc(x.name||x.key||'System')+' <small>'+esc(x.category||x.role||'')+' · level '+fmt(x.level||0)+'</small></span><span class="badge">'+esc(x.status||'ACTIVE')+' · '+fmt(x.effective_damage||x.effect||x.counter_force||x.base_damage||x.effective_output||0)+'</span></div>').join('')||'<div class="empty">No branch systems reported.</div>';document.getElementById('section').textContent='TECHNOLOGY';document.getElementById('title').textContent=title;document.getElementById('description').textContent=title+' — '+(d.formula||formula);document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">'+esc(branch.toUpperCase())+' BRANCH</div><h2>'+esc(title)+'</h2><p class="permission">'+esc(description)+'</p><div class="metric-grid"><div class="metric"><span>Technologies</span><strong>'+fmt(techs.length)+'</strong><small>Server catalogue</small></div><div class="metric"><span>Research queue</span><strong>'+fmt(d.queue_used||0)+' / '+fmt(d.queue_capacity||3)+'</strong><small>'+(d.queue_available?'AVAILABLE':'FULL')+'</small></div><div class="metric"><span>Branch effect</span><strong>'+fmt(d.damage_modifier||d.infiltration_modifier||d.counter_intelligence||0)+'</strong><small>Current calculated modifier</small></div></div></div><div class="card side-card"><div class="eyebrow">BRANCH NAVIGATION</div><h2>Technology systems</h2><div class="actions"><button class="button" onclick="openPage(\'technology\')">Technology Tree</button><button class="button" onclick="openPage(\'tech-offense\')">Offense</button><button class="button" onclick="openPage(\'tech-defense\')">Defense</button><button class="button" onclick="openPage(\'tech-covert\')">Covert</button><button class="button" onclick="openPage(\'tech-anti-covert\')">Anti-Covert</button></div></div><div class="card wide"><div class="eyebrow">RESEARCH TRACKS</div><h2>Upgrade paths</h2><table class="table"><thead><tr><th>Technology</th><th>Current</th><th>Next</th><th>Cost</th><th>Effect</th><th>Control</th></tr></thead><tbody>'+technologyRows(techs,csrf,branch==='tree'?'technology':branch==='defense'?'tech-defense':branch==='offense'?'tech-offense':branch==='covert'?'tech-covert':'tech-anti-covert')+'</tbody></table></div><div class="card side-card"><div class="eyebrow">RESEARCH QUEUE</div><h2>Queued research</h2>'+queue+'</div><div class="card wide"><div class="eyebrow">SYSTEM TELEMETRY</div><h2>Applied branch systems</h2>'+systems+'</div><div class="card wide"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Research contract</h2><p class="permission">Action: <code>technology</code>. Research is authenticated, CSRF-protected, prerequisite-checked, queue-limited, resource-validated, and committed transactionally.</p>'+['technologies','technology_prerequisites','player_technologies','research_queues','player_resources','game_events'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'</div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','locked','insufficient-resource','queued','success','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>'}
