function weaponRepairPage(){const r=state.repair||{};const items=r.items||[];const damaged=r.damaged||[];const csrf=state.csrf||'';const formatTime=s=>{s=Number(s||0);return s<60?s+' sec':Math.floor(s/60)+' min '+(s%60)+' sec'};const rows=(items.length?items:[{id:0,name:'No weapons in inventory',category:'—',quantity:0,durability:0,max_durability:100,condition_percent:0,missing_durability:0,tier:1,repair_cost:0,queue_seconds:0,repairable:false}]).map(w=>'<tr><td><strong>'+esc(w.name)+'</strong><small>'+esc(w.category)+'</small></td><td>'+fmt(w.quantity)+'</td><td>'+fmt(w.durability)+' / '+fmt(w.max_durability)+'</td><td>'+fmt(w.condition_percent)+'%</td><td>'+fmt(w.missing_durability)+'</td><td>'+fmt(w.tier)+'</td><td>'+fmt(w.repair_cost)+' N</td><td>'+formatTime(w.queue_seconds)+'</td><td>'+(w.repairable?'<form method="post" action="actions/game.php" class="inline-form">'+csrf+'<input type="hidden" name="action" value="weapon_repair"><input type="hidden" name="redirect" value="repair"><input type="hidden" name="weapon_id" value="'+esc(String(w.id))+'"><button class="button" type="submit">Repair weapon</button></form>':'<span class="badge good">READY</span>')+'</td></tr>').join('');const damagedRows=(damaged.length?damaged:[{name:'No damaged weapons',missing_durability:0,repair_cost:0,queue_seconds:0}]).map(w=>'<div class="row"><div><strong>'+esc(w.name)+'</strong><small>'+fmt(w.missing_durability)+' durability missing · '+formatTime(w.queue_seconds)+'</small></div><strong>'+fmt(w.repair_cost)+' N</strong></div>').join('');document.getElementById('section').textContent='ARMORY';document.getElementById('title').textContent='Weapon Repair';document.getElementById('description').textContent='Weapon Repair — '+(r.formula||'repair cost = missing durability × weapon tier × repair multiplier');document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">PAGE DETAILS</div><h2>Weapon Repair</h2><p class="permission">'+esc(r.f