function enemyIntelligencePage(){const t=state.enemy_intelligence||{};const csrf=state.csrf||'';const targets=t.targets||[];const rows=targets.map(x=>'<tr><td><strong>'+esc(x.name)+'</strong><small>'+esc(x.race)+' · #'+fmt(x.rank)+' · '+esc(x.owner_name||'Unclaimed realm')+'</small></td><td>'+fmt(x.attack)+'</td><td>'+fmt(x.defense)+'</td><td>'+fmt(x.covert)+'</td><td>'+fmt(x.observation_quality)+'%</td><td>'+fmt(x.freshness)+'%</td><td>'+fmt(x.counter_adjustment)+'×</td><td><strong>'+fmt(x.confidence)+'%</strong></td><td>'+esc(x.last_observation||'No observation')+'</td><td><span class="badge">'+esc(x.classification)+'</span></td><td>'+(x.report_id?'<form method="post" action="actions/game.php" class="inline-form">'+csrf+'<input type="hidden" name="action" value="read_report"><input type="hidden" name="redirect" value="enemy-intelligence"><input type="hidden" name="report_kind" value="intelligence"><input type="hidden" name="report_id" value="'+fmt(x.report_id)+'"><button class="button" type="submit">Open report</button></form>':'<span class="badge">NO REPORT</span>')+'</td></tr>').join('');document.getElementById('section').textContent='INTELLIGENCE';document.getElementById('title').textContent='Enemy Intelligence';document.getElementById('description').textContent='Enemy Intelligence — '+(t.formula||'intelligence confidence = observation quality × freshness × counter-intelligence adjustment');document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">PAGE DETAILS</div><h2>Enemy Intelligence</h2><p class="permission">'+esc(t.formula||'intelligence confidence = observation quality × freshness × counter-intelligence adjustment')+'</p><div class="metric-grid"><div class="metric"><span>Known targets</span><strong>'+fmt(t.target_count||0)+'</strong><small>Open realms available for intelligence review</small></div><div class="metric"><span>Confidence scores</span><strong>'+fmt(t.classified_count||0)+'</strong><small>Targets backed by classified observations</small></div><div class="metric"><span>Observation model</span><strong>Q × F × CI</strong><small>Quality × freshness × counter-intelligence</small></div></div></div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Report access</h2><p class="permission">Verify recipient or owner, then return classified payload.</p><div class="row"><span>Classified targets</span><strong>'+fmt(t.classified_count||0)+'</strong></div><p class="permission">authenticated commander · report classification permitted</p></div><div class="card wide"><div class="eyebrow">KNOWN TARGETS</div><h2>Confidence and last observation</h2><table class="table"><thead><tr><th>Target</th><th>Attack</th><th>Defense</th><th>Covert</th><th>Observation</th><th>Freshness</th><th>CI adjust.</th><th>Confidence</th><th>Last observation</th><th>Classification</th><th>Control</th></tr></thead><tbody>'+(rows||'<tr><td colspan="11">No known enemy targets</td></tr>')+'</tbody></table></div><div class="card side-card"><div class="eyebrow">CONFIDENCE SCORES</div><h2>Intelligence quality</h2><div class="row"><span>Known targets</span><strong>'+fmt(t.target_count||0)+'</strong></div><div class="row"><span>Classified reports</span><strong>'+fmt(t.classified_count||0)+'</strong></div><p class="permission">Confidence falls as observations become stale and is adjusted by target counter-intelligence relative to commander capability.</p></div><div class="card wide"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: read-only</p>'+['intelligence_reports','players','target_realms','player_resources'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">Report access verifies ownership, classification, authentication, CSRF, RBAC, cooldown, and transaction rules.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['loading','ready','empty','protected','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>'}

