head><tbody>'+(rows||'<tr><td colspan="8">No accessible sectors in this galaxy.</td></tr>')+'</tbody></table></div><div class="card side-card"><div class="eyebrow">REALM OWNERSHIP</div><h2>Ownership summary</h2><div class="row"><span>Known commander realms</span><strong>'+fmt((g.realm_ownership||{}).known_realms||0)+'</strong></div><div class="row"><span>Occupied mapped planets</span><strong>'+fmt((g.realm_ownership||{}).occupied_planets||0)+'</strong></div><p class="permission">Ownership counts are summarized server-side; coordinate details remain scoped to authenticated access.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','empty','protected','error'].map(s=>'<div class="row"><span>'+s+'</span><span class="badge">HANDLED</span></div>').join('')+'</div><div class="card wide"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: universe_galaxies</p>'+['universe_galaxies','universe_sectors','universe_solar_systems','universe_planets','universe_discoveries','target_realms','game_events'].map(t=>'<span class="badge">'+t+'</span> ').join('')+'<p class="permission">Galaxy selection validates active identifiers, coordinate scope, scan permission, and authenticated commander access before loading the map.</p></div></div>'}function ascensionPage(){const a=state.ascension||{},p=a.player||{},pr=a.progression||{},r=a.requirements||{},rew=a.reward||{},tech=a.technologies||{},cd=a.cooldown||{};const csrf=state.csrf||'';const techRows=['siege','fortification','infiltration','detection'].map(k=>'<div class="row"><span>'+k+'</span><strong>'+fmt(tech[k]||0)+' / '+fmt(r.technology_level||5)+'</strong></div>').join('');document.getElementById('section').textContent='ACCOUNT';document.getElementById('title').textContent='Ascension';document.getElementById('description').textContent='Ascension — '+(a.formula||'ascension reward = completed tier mastery × glory multiplier');document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">ELIGIBILITY</div><h2>Ascension eligibility <span class="badge '+(a.eligible?'good':'')+'">'+(a.eligible?'READY':'LOCKED')+'</span></h2><div class="metric-grid"><div class="metric"><span>Progression</span><strong>Tier '+fmt(pr.tier||0)+' · Level '+fmt(pr.level||0)+'</strong><small>Required: Tier '+fmt(r.tier||21)+' · Level '+fmt(r.level||23)+'</small></div><div class="metric"><span>Glory</span><strong>'+fmt(p.glory||0)+' / '+fmt(r.glory||2500)+'</strong><small>Required Glory balance</small></div><div class="metric"><span>Reputation</span><strong>'+fmt(p.reputation||0)+' / '+fmt(r.reputation||1500)+'</strong><small>Required Reputation balance</small></div></div><div class="row"><span>Tier mastery</span><strong>'+fmt(pr.mastery||0)+'</strong></div></div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Ascend</h2><p class="permission">Lock progression, validate requirements, write the ascension, and grant the permanent result.</p><button type="button" class="button" id="ascension-check">Check eligibility</button><form method="post" action="actions/game.php" class="action-form">'+csrf+'<input type="hidden" name="action" value="ascend"><input type="hidden" name="redirect" value="ascension"><label>Ascended race<input type="text" name="ascended_race" value="Ascended '+(state.race||'Commander')+'" maxlength="80" required></label><button class="button dark" type="submit" '+(a.eligible?'':'disabled')+'>Ascend</button></form><div class="row"><span>Cooldown</span><span class="badge '+(cd.state==='ready'?'good':'')+'">'+esc(cd.state||'ready')+'</span></div></div><div class="card wide"><div class="eyebrow">GLORY BALANCE</div><h2>Resource requirements</h2><div class="row"><span>Glory available</span><strong>'+fmt(p.glory||0)+'</strong></div><div class="row"><span>Reputation available</span><strong>'+fmt(p.reputation||0)+'</strong></div><div class="row"><span>Ascensions completed</span><strong>'+fmt(p.ascension_count||0)+'</strong></div><p class="permission">Requirements are read and validated inside the transaction; client values are display-only.</p></div><div class="card side-card"><div class="eyebrow">REQUIRED TECHNOLOGIES</div><h2>Technology gates</h2>'+techRows+'<p class="permission">Every listed technology must meet the required level of '+fmt(r.technology_level||5)+'.</p></div><div class="card wide"><div class="eyebrow">TIER TRANSITION</div><h2>Completion and reset</h2><div class="row"><span>Current mastery</span><strong>'+fmt(rew.mastery||pr.mastery||0)+'</strong></div><div class="row"><span>Glory multiplier</span><strong>'+fmt(rew.glory_multiplier||2)+'×</strong></div><div class="row"><span>Transition</span><strong>Maximum tier → Ascended state</strong></div><p class="permission">A successful transaction records the ascension, resets the active progression track for the next cycle, and grants the permanent ascension-point result.</p></div><div class="card side-card"><div class="eyebrow">PERMANENT BONUSES</div><h2>Ascension reward</h2><div class="metric"><span>Permanent ascension points</span><strong>+'+fmt(rew.permanent_bonus||rew.ascension_points||0)+'</strong><small>Reward = completed tier mastery × Glory multiplier</small></div></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','locked','insufficient-resource','success','error'].map(s=>'<div class="row"><span>'+s+'</span><span class="badge">HANDLED</span></div>').join('')+'</div><div class="card wide"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: ascend</p>'+['ascension_states','ascensions','glory_reputation','progression_entities','player_technologies','players','player_cooldowns','game_events'].map(t=>'<span class="badge">'+t+'</span> ').join('')+'<p class="permission">Writes are authenticated, CSRF-protected, RBAC-scoped, ownership-validated, tier-checked, resource-checked, cooldown-checked, and transactional.</p></div></div>';const check=document.getElementById('ascension-check');if(check)check.onclick=()=>{const b=document.getElementById('global-feedback');if(b){b.style.display='block';b.dataset.state=a.eligible?'ready':'locked';b.textContent=a.eligible?'Eligibility confirmed: all Ascension requirements are satisfied.':'Eligibility checked: complete the listed progression, Glory, Reputation, and technology requirements before ascending.'}}}function vacationPage(){const v=state.vacation||{},b=v.blocking_operations||{},cd=v.cooldown||{};const active=Boolean(v.active);const csrf=state.csrf||'';document.getElementById('section').textContent='ACCOUNT';document.getElementById('title').textContent='Vacation Mode';document.getElementById('description').textContent='Vacation Mode — '+(v.formula||'vacation protection = account lock + fleet lock + colony production pause');const missions=(b.missions||[]).map(m=>'<div class="row"><span>'+esc(m.mission_type||'MISSION')+'</span><strong>'+esc(m.status||'ACTIVE')+'</strong></div>').join('');document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">CURRENT PROTECTION</div><h2>Vacation protection <span class="badge '+(active?'good':'')+'">'+(active?'ACTIVE':'INACTIVE')+'</span></h2><div class="metric-grid"><div class="metric"><span>Account lock</span><strong>'+(active?'LOCKED':'OPEN')+'</strong><small>Mutating account actions are restricted.</small></div><div class="metric"><span>Fleet lock</span><strong>'+(active?'LOCKED':'OPEN')+'</strong><small>Fleet dispatch is paused during protection.</small></div><div class="metric"><span>Colony production</span><strong>'+(active?'PAUSED':'RUNNING')+'</strong><small>Turn settlement honors vacation state.</small></div></div></div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Activation rules</h2><form method="post" action="actions/game.php" class="action-form">'+csrf+'<input type="hidden" name="action" value="vacation"><input type="hidden" name="redirect" value="vacation"><label>Duration (days)<input type="number" name="days" min="1" max="30" value="7" required></label><button class="button dark" type="submit" '+(active||b.active_combat||cd.state==='cooldown'?'disabled':'')+'>Vacation mode</button></form><p class="permission">Authenticated commander · no active attack or raid fleets · cooldown satisfied · duration 1–30 days.</p></div><div class="card wide"><div class="eyebrow">COOLDOWN</div><h2>Activation cooldown</h2><div class="row"><span>State</span><span class="badge '+(cd.state==='ready'?'good':'')+'">'+esc(cd.state||'ready')+'</span></div><div class="row"><span>Remaining</span><strong>'+fmt(cd.remaining_seconds||0)+' seconds</strong></div><div class="row"><span>Blocking operations</span><strong>'+fmt(b.count||0)+'</strong></div>'+(missions||'<p class="permission">No active fleet operations are blocking activation.</p>')+'</div><div class="card side-card"><div class="eyebrow">RETURN SCHEDULE</div><h2>Protection window</h2><div class="row"><span>Starts</span><strong>'+esc(v.starts_at||'—')+'</strong></div><div class="row"><span>Returns</span><strong>'+esc(v.ends_at||'—')+'</strong></div><p class="permission">Protection expires automatically at the recorded return time. No client-side timer is trusted for enforcement.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','protected','cooldown','success','error'].map(s=>'<div class="row"><span>'+s+'</span><span class="badge">HANDLED</span></div>').join('')+'</div><div class="card wide"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: vacation</p>'+['vacation_states','protection_states','players','player_cooldowns','fleet_missions','battles','game_events'].map(t=>'<span class="badge">'+t+'</span> ').join('')+'<p class="permission">Protection activation is authenticated, CSRF-protected, RBAC-scoped, ownership-validated, combat-checked, cooldown-checked, and transactional.</p></div></div>'}function racePage(){
 const f=state.faction||{}, c=f.current||{}, p=f.player||{}, o=f.options||{}, races=o.races||[], governments=o.governments||[], csrf=state.csrf||'';
