 document.getElementById('content').innerHTML=`<div class="cc-grid"><div class="card wide"><div class="eyebrow">CURRENT FACTION</div><h2>${esc(c.race_name||'Unassigned')} <span class="badge good">${p.registration_complete?'REGISTERED':'PENDING'}</span></h2><div class="metric-grid"><div class="metric"><span>Faction bonus</span><strong>+${Number(c.bonus_percent||0).toFixed(0)}%</strong><small>${esc(c.bonus_label||'Select a race')}</small></div><div class="metric"><span>Government</span><strong>${esc(c.government_name||'Unassigned')}</strong><small>Political modifier profile</small></div><div class="metric"><span>Income modifier</span><strong>${Number(c.income_modifier||1).toFixed(2)}×</strong><small>Race × government</small></div></div><div class="row"><span>Applied combat profile</span><strong>${Number(c.attack_modifier||1).toFixed(2)}× attack · ${Number(c.defense_modifier||1).toFixed(2)}× defense</strong></div><div class="row"><span>Applied growth profile</span><strong>${Number(c.population_modifier||1).toFixed(2)}× population</strong></div></div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Atomic faction selection</h2><form method="post" action="actions/game.php" class="action-form">${csrf}<input type="hidden" name="action" value="select_registration_faction"><input type="hidden" name="redirect" value="race"><label>Race<select name="race_id" required>${raceOptions}</select></label><label>Government<select name="government_id" required>${govOptions}</select></label><button class="button dark" type="submit">Select race and government</button></form><p class="permission">Initial registration validates both faction selections and saves them atomically.</p></div><div class="card wide"><div class="eyebrow">AVAILABLE RACES</div><h2>Faction bonuses</h2><div class="cc-grid">${cards}</div></div><div class="card side-card"><div class="eyebrow">COMPATIBILITY RULES</div><h2>Selection eligibility</h2><div class="row"><span>Active races</span><strong>${fmt(races.length)}</strong></div><div class="row"><span>Active governments</span><strong>${fmt(governments.length)}</strong></div><div class="row"><span>Registration</span><span class="badge">${p.registration_complete?'COMPLETE':'REQUIRED'}</span></div><p class="permission">Every active government is compatible with every active race. Modifiers are multiplied server-side.</p></div><div class="card wide"><div class="eyebrow">GOVERNMENT REFORM</div><h2>Reform government</h2><form method="post" action="actions/game.php" class="action-form">${csrf}<input type="hidden" name="action" value="reform_government"><input type="hidden" name="redirect" value="race"><label>New government<select name="government_id" required>${govOptions}</select></label><button class="button" type="submit">Reform government</button></form><div class="row"><span>Reform cooldown</span><strong>${esc((f.cooldowns||{}).government_reform?.state||'ready')}</strong></div></div><div class="card side-card"><div class="eyebrow">PROTECTION</div><h2>Vacation mode</h2><form method="post" action="actions/game.php" class="action-form">${csrf}<input type="hidden" name="action" value="vacation"><input type="hidden" name="redirect" value="race"><label>Duration (days)<input type="number" name="days" min="1" max="30" value="1" required></label><button class="button" type="submit">Vacation mode</button></form><p class="permission">Sets vacation protection and records the state transition.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>${['ready','protected','cooldown','success','error'].map(s=>`<div class="row"><span>${s}</span><span class="badge">HANDLED</span></div>`).join('')}</div><div class="card wide"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Actions: change_race / select_registration_faction / reform_government / vacation</p>${['races','government_types','players','player_government_history','player_cooldowns','protection_states','vacation_states','game_events'].map(t=>`<span class="badge">${t}</span> `).join('')}<p class="permission">Writes are authenticated, CSRF-protected, RBAC-scoped, ownership-validated, cooldown-checked, and transactional.</p></div></div>`;
}
function alliancesPage(){const a=state.alliances||{},cap=a.capacity||{},rows=(a.alliances||[]).map(x=>`<div class="row"><div><strong>${esc(x.name||'Unnamed alliance')}</strong><small>${esc(x.tag||'')} · ${fmt(x.member_count||0)} members · founder #${fmt(x.founder_id||0)}</small></div><form method="post" action="actions/game.php" class="inline-form">${state.csrf||''}<input type="hidden" name="action" value="alliance_join"><input type="hidden" name="redirect" value="alliances"><input type="hidden" name="alliance_id" value="${fmt(x.id||0)}"><button class="button" type="submit">Join alliance</button></form></div>`).join('');const current=a.current?`<div class="row"><span>Current alliance</span><strong>${esc(a.current.name||'')}</strong></div><div class="row"><span>Role</span><span class="badge good">${esc(a.current.role||'member')}</span></div>`:'<div class="empty"><strong>No alliance membership.</strong><p>Create a new alliance or join an open alliance.</p></div>';const roster=(a.roster||[]).map(m=>`<div class="row"><div><strong>${esc(m.display_name||'Commander')}</strong><small>${esc(m.title||'')} · joined ${esc(m.joined_at||'')}</small></div><span class="badge">${esc(m.role||'member')}</span></div>`).join('');document.getElementById('section').textContent='SOCIAL';document.getElementById('title').textContent='Alliances';document.getElementById('description').textContent='Alliances — '+(a.formula||'alliance capacity = command level × alliance technology × government modifier');document.getElementById('content').innerHTML=`<div class="cc-grid"><div class="card wide"><div class="eyebrow">ALLIANCE IDENTITY</div><h2>Current membership</h2>${current}<div class="metric-grid"><div class="metric"><span>Command level</span><strong>${fmt(cap.command_level||1)}</strong><small>Commander authority</small></div><div class="metric"><span>Alliance technology</span><strong>${fmt(cap.technology_level||0)}</strong><small>Effective level</small></div><div class="metric"><span>Capacity</s