ng>Expedition ${esc(e.coordinate)}</strong><small>Risk ${Number(e.risk_score||0).toFixed(0)} · ${esc(e.resolved_at||'')}</small></div><span class="badge ${e.outcome==='positive'||e.outcome==='discovery'?'good':''}">${esc(e.outcome)}</span></div>`).join('');const noticeRows=notifications.map(n=>`<div class="row"><div><strong>${esc(n.title)}</strong><small>${esc(n.body)} · ${esc(n.created_at||'')}</small></div>${Number(n.is_read)?'<span class="badge">READ</span>':`<form method="post" action="actions/game.php" class="inline-form">${csrf}<input type="hidden" name="action" value="notification_read"><input type="hidden" name="redirect" value="events"><input type="hidden" name="notification_id" value="${fmt(n.id)}"><button class="button" type="submit">Mark read</button></form>`}</div>`).join('');document.getElementById('section').textContent='OPERATIONS';document.getElementById('title').textContent=mode==='events'?'Events & Notifications':'Missions & Quests';document.getElementById('description').textContent=mode==='events'?'Asynchronous events, expedition reports, notifications, and world-state feedback.':'Fleet missions, expeditions, objectives, achievements, and officer effects.';document.getElementById('content').innerHTML=`<div class="cc-grid"><div class="card wide"><div class="eyebrow">${mode==='events'?'EXPEDITION REPORTS':'FLEET MISSIONS'}</div><h2>${mode==='events'?'Exploration outcomes':'Active and recent missions'}</h2>${mode==='events'?(eventRows||'<div class="empty">No expedition reports are available.</div>'):(missionRows||'<div class="empty">No fleet missions are scheduled.</div>')}</div><div class="card wide"><div class="eyebrow">QUESTS</div><h2>Objectives and rewards</h2>${questRows||'<div class="empty">No active objectives are available.</div>'}</div><div class="card side-card"><div class="eyebrow">ACHIEVEMENTS</div><h2>Empire milestones</h2>${achievements.map(a=>`<div class="row"><span>${esc(a.title)}</span><strong>${fmt(a.progress)} / ${fmt(a.metric_tar