ation, discovery filtering, ownership classification, and navigation identifiers are server-authoritative.</p>'+['universe_galaxies','universe_sectors','universe_solar_systems','universe_planets','universe_discoveries','player_colonies'].map(t=>'<span class="badge">'+t+'</span> ').join('')+'</details></div></div>';document.querySelectorAll('.coordinate-intent').forEach(b=>b.onclick=()=>{selected=b.dataset.route;render()})}
