document.getElementById('section').textContent=String(p.group_label||s.group_label||'SYSTEM').toUpperCase();document.getElementById('title').textContent=title;document.getElementById('description').textContent=hero;document.getElementById('content').innerHTML='<div class="cc-grid generated-page"><div class="card wide"><div class="eyebrow">SYSTEM CONSOLE</div><h2>'+esc(title)+'</h2><p class="permission">'+esc(hero)+'</p><div class="metric-grid"><div class="metric"><span>Mechanic</span><strong>SERVER VERIFIED</strong><small>'+esc(mechanic)+'</small></div><div class="metric"><span>Controls</span><strong>'+fmt(controls.length)+'</strong><small>Validated page operations</small></div><div class="metric"><span>Actions</span><strong>'+fmt(actions.length)+'</strong><small>Authenticated contracts</small></div><div class="metric"><span>Data scope</span><strong>'+fmt(tables.length)+'</strong><small>Scoped database tables</small></div></div></div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Available operations</h2><div class="button-stack">'+controlMarkup+'</div><div id="generic-feedback" class="feedback" style="display:none"></div></div><div class="card wide"><div class="eyebrow">FEATURES</div><h2>Subsystem capabilities</h2>'+list(features)+'</div><div class="card wide"><div class="eyebrow">SUB-FEATURES</div><h2>Operational detail</h2>'+list(subs)+'</div><div class="card side-card"><div class="eyebrow">SYSTEM DESIGN</div><h2>Server contract</h2><p class="permission">'+esc(mechanic)+'</p><div class="row"><span>Permission</span><strong>'+esc(s.permission||d.permission||'authenticated commander')+'</strong></div><div class="row"><span>Actions</span><strong>'+esc(actions.join(' · ')||'read-only')+'</strong></div><div class="row"><span>Tables</span><strong>'+esc(tables.join(' · ')||'none')+'</strong></div></div><div class="card wide"><div class="eyebrow">INFORMATION</div><h2>Commander reference</h2>'+list(info)+'</div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+stateRows+'</div></div>';bindIntentButtons('.generated-intent',selected)}
function submitIntent(action,redirect,payload){const form=document.createElement('form');form.method='POST';form.action='actions/game.php';form.style.display='none';form.innerHTML=state.csrf||'';const add=(name,value)=>{const input=document.createElement('input');input.type='hidden';input.name=name;input.value=value==null?'':String(value);form.appendChild(input)};add('action',action);add('redirect',redirect||selected||'dashboard');Object.entries(payload||{}).forEach(([name,value])=>add(name,value));document.body.appendChild(form);form.submit()}function bindIntentButtons(selector,redirect){document.querySelectorAll(selector).forEach(button=>button.onclick=()=>{let action=button.dataset.action||'';const payload={};if(action==='choose_target'){submitIntent('read_target_board','targets',{});return}if(action==='review_reports'){window.location.href='game.php?page=attack-log';return}if(action==='open_colony'){window.location.href='game.php?page=planet-list';return}if(action==='dispatch_fleet'){window.location.href='game.php?page=missions';return}if(action==='progression_advance'){payload.entity_category='player';payload.entity_key='player_core';}if(button.dataset.target)payload.target_id=button.dataset.target;if(button.dataset.weapon)payload.weapon_type_id=button.dataset.weapon;if(button.dataset.report)payload.report_id=button.dataset.report;if(button.dataset.reportKind)payload.report_kind=button.dataset.reportKind;if(action==='weapon_buy')payload.quantity=button.dataset.quantity||1;if(action==='set_defcon')payload.level=button.dataset.level||2;if(action==='message_read'&&button.dataset.message)payload.message_id=button.dataset.message;if(action==='read_report'&&!payload.report_id){const feedback=document.getElementById(button.dataset.feedback||'feedback');if(feedback){feedback.style.display='block';feedback.textContent='Select a report before opening it.'}return}submitIntent(action,redirect,payload)})}
function premiumPage(){const k=selected||'premium';const data={premium:{title:'Premium Hub',sub:'Commander premium systems, seasonal rewards, and bounded convenience services.',items:[['season_pass_01','Season Pass','Unlock the seasonal reward track and premium objectives.'],['officer_logistics','Logistics Officer','10% logistics modifier for 24 hours.'],['service_queue','Queue Priority Service','Reduce one active queue completion time by 15%.']]},store:{title:'Premium Store',sub:'Transparent catalogue with server-validated prices and atomic wallet settlement.',items:[['season_pass_01','Empire Season Pass','Seasonal reward track and premium objectives.'],['service_queue','Queue Priority Service','Bounded queue convenience service.'],['service_colony_scan','Colony Scan Packet','One additional validated telemetry report.']]},commander:{title:'Commander',sub:'Daily reward, season pass progression, and wallet state.',items:[['daily_claim','Daily premium claim','Claim 100 Dark Matter once every 24 hours.'],['season_pass_01','Activate Season Pass','Unlock seasonal progression.']]},'premium-officers':{title:'Premium Officers',sub:'Time-limited officers with explicit effects and expiry tracking.',items:[['officer_logistics','Logistics Officer','Construction and fleet logistics modifier.'],['officer_science','Science Officer','Research output modifier.']]},'premium-services':{title:'Premium Services',sub:'Bounded convenience services with auditable credits and cooldowns.',items:[['service_queue','Queue Priority Service','One queue speed activation.'],['service_colony_scan','Colony Scan Packet','One validated colony scan credit.']]}};const d=data[k]||data.premium;const dm=state.resources?.dark_matter??state.resources?.darkMatter??0;const cards=d.items.map(([key,name,desc])=>`<div class="panel premium-offer"><div><span class="panel-kicker">PREMIUM OFFER</span><h3>${esc(name)}</h3><p>${esc(desc)}</p></div><div class="premium-actions">${key==='daily_claim'?`<button class="button" data-action="premium_claim_daily" data-redirect="commander">Claim daily reward</button>`:`<button class="button" data-action="premium_activate" data-item="${esc(key)}" data-redirect="${esc(k)}">Activate</button><button class="button secondary" data-action="premium_purchase" data-item="${esc(key)}" data-redirect="${esc(k)}">Purchase</button>`}</div></div>`).join('');document.getElementById('content').innerHTML=`<div class="page premium-page"><div class="page-heading"><div><span class="eyebrow">PREMIUM SYSTEMS</span><h1>${esc(d.title)}</h1><p>${esc(d.sub)}</p></div><span class="badge good">SERVER VERIFIED</span></div><section class="metric-strip"><div class="metric"><span>Dark Matter</span><strong>${fmt(dm)}</strong><small>Premium wallet balance</small></div><div class="metric"><span>Season Pass</span><strong>${state.premium?.season_pass?'ACTIVE':'AVAILABLE'}</strong><small>Progression track</small></div><div class="metric"><span>Daily Claim</span><strong>100 DM</strong><small>24-hour cooldown</small></div><div class="metric"><span>Audit</span><strong>LOCKED</strong><small>Atomic transaction ledger</small></div></section><section class="premium-layout"><div><div class="section-heading"><span class="panel-kicker">CATALOGUE</span><h2>Premium controls</h2></div>${cards}</div><aside class="panel premium-contract"><span class="panel-kicker">SYSTEM DESIGN</span><h2>Server-authoritative premium economy</h2><p>Prices, rewards, cooldowns, ownership, and effect expiry are resolved on the server. The client submits only an item key and bounded intent.</p><div class="contract-row"><span>Wallet lock</span><b>FOR UPDATE</b></div><div class="contract-row"><span>Feedback</span><b>READY · COOLDOWN · ERROR</b></div><div class="contract-row"><span>Audit</span><b>GAME EVENTS</b></div></aside></section><section class="panel"><div class="panel-kicker">TRANSACTION HISTORY</div><h2>Recent premium activity</h2><p>Purchases and activations are persisted with player ownership and timestamps.</p><span class="badge">READ ONLY</span></section></div>`;bindPremiumButtons()}
function bindPremiumButtons(){document.querySelectorAll('[data-action^="premium_"]').forEach(b=>b.onclick=()=>{const action=b.dataset.action,payload={item_key:b.dataset.item||'',quantity:1};if(action==='premium_claim_daily')delete payload.item_key;submitIntent(action,b.dataset.redirect||selected,payload)})}
function render(){const feedback=state.feedback||{};let banner=document.getElementById('global-feedback');if(!banner){banner=document.createElement('div');banner.id='global-feedback';banner.className='feedback';document.getElementById('content').before(banner)}banner.textContent=feedback.message||'';banner.dataset.state=feedback.state||'ready';banner.style.display=feedback.message?'block':'none';renderNav((document.getElementById('search').value||'').toLowerCase().trim());if(selected==='dashboard')commandCenter();else if(selected==='account-info')accountInfo();else if(selected==='resources')economyPage();else if(selected==='income')breakdownPage();else if(selected==='military-stats')militaryStatsPage();else if(selected==='sabotage')sabotagePage();else if(selected==='attack-log')reportsPage();else if(selected==='weapons')weaponsPage();else if(selected==='weapon-market')weaponMarketPage();else if(selected==='tech-defense')defenseTechnologyPage();else if(selected==='repair')weaponRepairPage();else if(selected==='units'||selected==='training')unitTrainingPage();else if(selected==='miners')workforcePage();else if(selected==='super-units')superUnitsPage();else if(selected==='unit-production')unitProductionPage();else if(selected==='technology')technologyTreePage();else if(selected==='tech-offense')offenseTechnologyPage();else if(selected==='tech-covert')covertTechnologyPage();else if(selected==='tech-anti-covert')antiCovertTechnologyPage();else if(selected==='spy-log')spyLogPage();else if(selected==='enemy-intelligence')enemyIntelligencePage();else if(selected==='race')racePage();else if(selected==='vacation')vacationPage();else if(selected==='ascension')ascensionPage();else if(selected==='galaxies')galaxyMapPage();else if(selected==='sectors')sectorMapPage();else if(selected==='planet-list')planetListPage();else if(selected==='settlement')settlementPage();else if(selected==='ship')mothershipPage();else if(selected==='solar-systems')solarSystemsPage();else if(selected==='universe-planets')universePlanetsPage();else if(selected==='moons')moonRegistryPage();else if(selected==='coordinates')coordinateSearchPage();else if(selected==='planet-bonuses')planetBonusesPage();else if(selected==='planet-defenses')planetDefensesPage();else if(selected==='exploration')explorationPage();else if(selected==='alliances')alliancesPage();else if(selected==='messages')messagesPage();else if(['premium','store','commander','premium-officers','premium-services'].includes(selected))premiumPage();else if(selected==='missions'||selected==='events')operationsPage(selected);else if(['targets','spy'].includes(selected))attackPage(selected);else genericPage()};document.getElementById('search').oninput=()=>render();loadAccountPreferences();render();
</script><!-- page-intent controls use authenticated generated intents --><script src="assets/generated-page-interactions.js"></script></body></html>
